      "name": "تیکت — عدم پاسخگویی توسعه‌دهنده (خرید) — معرفی",
      "startX": 100,
      "startY": 3180,
      "endTransition": null,
      "cards": [
        {
          "id": "b8056178-d39e-42c7-a61b-01a3b29832ab",
          "type": "SEND_MESSAGE",
          "content": {
