          "label": "Set imageUrl",
          "targetVariable": "imageUrl",
          "value": "{{(history.allMessages || '').includes('<urls>') ? (((history.allMessages || '').split('<urls>').pop().split('</urls>')[0] || '')) : ''}}"
        },
        {
          "id": "bbdbccb7-51cc-4206-b849-3133f21c1d54",
          "type": "SET_VARIABLE",
          "label": "Set ticketSubject",
          "targetVariable": "ticketSubject",
          "value": "{{'بروز خطای ' + workflow.errorCode + ' در هنگام ' + workflow.installContext + ' برنامه ' + workflow.appName}}"
        },
        {
          "id": "4886a1a6-2cb9-4477-8d36-4755fffb6dd1",
          "type": "SET_VARIABLE",
          "label": "Set ticketBody",
          "targetVariable": "ticketBody",
          "value": "{{'کاربر در زمان ' + workflow.installContext + ' برنامه ' + workflow.appName + ' کد خطای ' + workflow.errorCode + ' دریافت می کند. علی‌رغم راهنمایی ارائه‌شده (به‌روزرسانی بازار، پاک‌سازی با برنامه کلینر و آزادسازی فضا) همچنان موفق به نصب برنامه نشده است. خواهشمند است با توجه به اطلاعاتی که این کاربر در اختیار هوشواره پشتیبانی کافه بازار قرار داده است، موضوع را پیگیری کنید:\\n' + '1- مدل گوشی کاربر: ' + (workflow.deviceModel || '-') + '\\n2- نسخه سیستم عامل گوشی کاربر: ' + (workflow.androidVersion || '-') + '\\n3- میزان حافظه خالی گوشی کاربر: ' + (workflow.freeStorage || '-') + '\\n4- شماره نسخه بازار: ' + (workflow.bazaarVersion || '-') + '\\n5- شناسه دستگاه: ' + (workflow.deviceId || '-') + (((workflow.imageUrl || '') != '') ? '\\n6- تصویری که کاربر از صفحه‌ی برنامه ' + workflow.appName + ' در کافه بازار گرفته است از طریق [این لینک](' + workflow.imageUrl + ') در دسترس است.' : '')}}"
        }
      ]
    },
