      "id": "beabac6b-8c5e-472c-b337-0201ac7d4e9c",
      "name": "تیکت — عدم پاسخگویی توسعه‌دهنده (خرید) — معرفی",
      "startX": 100,
      "startY": 3180,
      "endTransition": null,
      "cards": [
